interface AddAthleteModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  tournament: Tournament;
  divisions: Division[];
  selectedDivisionId: string;
  onSuccess: () => Promise<void> | void;
}

const SOURCES: AddAthleteSource[] = ['FRIENDS', 'CLUB', 'DIRECT'];

export function AddAthleteModal({ open, onOpenChange, tournament, divisions, selectedDivisionId, onSuccess }: AddAthleteModalProps) {
  const t = useTranslations('AddAthlete');
  const initialDivisionId = selectedDivisionId || divisions[0]?.id || '';
  const [divisionId, setDivisionId] = React.useState(initialDivisionId);
  const [source, setSource] = React.useState<AddAthleteSource>('FRIENDS');
  const [search, setSearch] = React.useState('');
  const [rows, setRows] = React.useState<AddAthleteCandidate[]>([]);
  const [nextCursor, setNextCursor] = React.useState<string | null>(null);
  const [selectedIds, setSelectedIds] = React.useState<string[]>([]);
  const [pageLoading, setPageLoading] = React.useState(false);
  const [submitting, setSubmitting] = React.useState(false);
  const [players, setPlayers] = React.useState([{ displayName: '', email: '', phone: '' }]);
  const [teamName, setTeamName] = React.useState('');
  const [organizerNote, setOrganizerNote] = React.useState('');
  const selectedDivision = divisions.find((division) => division.id === divisionId);
  const matchType = selectedDivision?.matchType ?? tournament.matchType;
  const maxPlayers = matchType === 'DOUBLES' || matchType === 'MIXED_DOUBLES' ? 2 : 1;

  const loadCandidates = React.useCallback(async (cursor?: string, append = false) => {
    if (source === 'DIRECT' || !open) return;
    setPageLoading(true);
    try {
      const response = await tournamentsApi.getAddAthleteCandidates(tournament.id, {
        source,
        divisionId: divisionId || undefined,
        search: search.trim() || undefined,
        cursor,
        limit: 20,
      });
      const payload = response.data?.data ?? response.data;
      setRows((current) => append ? [...current, ...(payload?.rows ?? [])] : (payload?.rows ?? []));
      setNextCursor(payload?.nextCursor ?? null);
    } catch (error) {
      toast.error(getErrorMessage(error));
      if (!append) setRows([]);
      setNextCursor(null);
    } finally {
      setPageLoading(false);
    }
  }, [divisionId, open, search, source, tournament.id]);

  React.useEffect(() => {
    if (open && source !== 'DIRECT') void loadCandidates();
  }, [loadCandidates, open, source]);

  React.useEffect(() => {
    if (!open) return;
    setDivisionId(initialDivisionId);
    setSource('FRIENDS');
    setSearch('');
    setSelectedIds([]);
    setPlayers(Array.from({ length: maxPlayers }, () => ({ displayName: '', email: '', phone: '' })));
    setTeamName('');
    setOrganizerNote('');
  }, [initialDivisionId, maxPlayers, open]);

  const switchSource = (value: AddAthleteSource) => {
    setSource(value);
    setSelectedIds([]);
    setRows([]);
    setNextCursor(null);
  };

  const submit = async () => {
    if (submitting) return;
    if (source === 'DIRECT' && players.some((player) => !player.displayName.trim())) return;
    if (source !== 'DIRECT' && selectedIds.length !== maxPlayers) return;
    setSubmitting(true);
    try {
      const response = await tournamentsApi.addAthletes(tournament.id, {
        source,
        ...(divisionId ? { divisionId } : {}),
        ...(teamName.trim() ? { teamName: teamName.trim() } : {}),
        players: source === 'DIRECT'
          ? players.map((player, index) => ({
              displayName: player.displayName.trim(),
              ...(player.email.trim() ? { email: player.email.trim() } : {}),
              ...(player.phone.trim() ? { phone: player.phone.trim() } : {}),
              role: index === 0 ? 'MAIN' as const : 'PARTNER' as const,
            }))
          : selectedIds.map((userId, index) => ({ userId, role: index === 0 ? 'MAIN' as const : 'PARTNER' as const })),
        ...(organizerNote.trim() ? { organizerNote: organizerNote.trim().slice(0, 280) } : {}),
      });
      if (!response.data) throw new Error(t('addFailed'));
      const payload = response.data.data ?? response.data;
      const claimToken = payload?.claim?.claimToken;
      if (claimToken) window.prompt(t('claimTokenHandoff'), claimToken);
      toast.success(t('addSuccess'));
      onOpenChange(false);
      await onSuccess();
    } catch (error) {
      toast.error(getErrorMessage(error));
    } finally {
      setSubmitting(false);
    }
  };

  const canSubmit = source === 'DIRECT'
    ? players.every((player) => player.displayName.trim().length > 0)
    : selectedIds.length === maxPlayers;

  return (
    <Modal open={open} onOpenChange={onOpenChange}>
      <ModalContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl" aria-describedby="add-athlete-description">
        <ModalHeader>
          <ModalTitle>{t('title')}</ModalTitle>
          <ModalDescription id="add-athlete-description">{t('description')}</ModalDescription>
        </ModalHeader>
        <div className="space-y-4">
          {divisions.length > 1 && <div>
            <label htmlFor="add-athlete-division" className="mb-1 block text-sm font-medium">{t('division')}</label>
            <select id="add-athlete-division" value={divisionId} onChange={(event) => { setDivisionId(event.target.value); setSelectedIds([]); }} className="h-10 w-full rounded-md border border-slate-300 bg-white px-3 text-sm">
              {divisions.map((division) => <option key={division.id} value={division.id}>{division.name}</option>)}
            </select>
          </div>}
          <div role="tablist" aria-label={t('source')} className="flex flex-wrap gap-2">
            {SOURCES.map((option) => <button key={option} type="button" role="tab" aria-selected={source === option} onClick={() => switchSource(option)} className={`min-h-10 rounded-md border px-3 text-sm font-medium focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 ${source === option ? 'border-blue-600 bg-blue-50 text-blue-800' : 'border-slate-300 text-slate-700 hover:bg-slate-50'}`}>{t(`source${option}`)}</button>)}
          </div>
          {source !== 'DIRECT' ? <>
            <label className="relative block">
              <span className="sr-only">{t('search')}</span>
              <Search aria-hidden="true" className="absolute left-3 top-3 h-4 w-4 text-slate-400" />
              <Input aria-label={t('search')} value={search} onChange={(event) => setSearch(event.target.value)} className="pl-9" placeholder={t('search')} />
            </label>
            <div aria-live="polite" aria-busy={pageLoading} className="max-h-64 space-y-1 overflow-y-auto rounded-md border border-slate-200 p-2">
              {pageLoading && rows.length === 0 ? <p className="p-4 text-center text-sm text-slate-500"><Loader2 className="mr-2 inline h-4 w-4 animate-spin" />{t('loading')}</p> : rows.length === 0 ? <p className="p-4 text-center text-sm text-slate-500">{t('empty')}</p> : rows.map((candidate) => (
                <label key={candidate.userId} className="flex cursor-pointer items-center gap-3 rounded-md p-2 hover:bg-slate-50">
                  <input type="checkbox" checked={selectedIds.includes(candidate.userId)} disabled={!selectedIds.includes(candidate.userId) && selectedIds.length >= maxPlayers} onChange={() => setSelectedIds((current) => current.includes(candidate.userId) ? current.filter((id) => id !== candidate.userId) : [...current, candidate.userId])} />
                  {candidate.avatarUrl ? <img src={candidate.avatarUrl} alt="" className="h-9 w-9 rounded-full object-cover" /> : <span aria-hidden="true" className="inline-flex h-9 w-9 items-center justify-center rounded-full bg-blue-100 text-sm font-semibold text-blue-700">{candidate.displayName.trim().split(/\s+/).map((part) => part[0]).slice(-2).join('').toUpperCase()}</span>}
                  <span className="text-sm font-medium">{candidate.displayName}</span>
                </label>
              ))}
              {nextCursor && <Button type="button" variant="outline" size="sm" disabled={pageLoading} onClick={() => void loadCandidates(nextCursor, true)} className="w-full">{t('nextPage')}</Button>}
            </div>
            <p className="text-xs text-slate-500">{t('selectedCount', { selected: selectedIds.length, required: maxPlayers })}</p>
          </> : <>
            {players.map((player, index) => <div key={index} className="grid gap-3 rounded-md border border-slate-200 p-3 sm:grid-cols-3">
              <div><label htmlFor={`add-athlete-name-${index}`} className="mb-1 block text-sm font-medium">{t('name')} <span aria-hidden="true">*</span></label><Input id={`add-athlete-name-${index}`} required value={player.displayName} onChange={(event) => setPlayers((current) => current.map((item, i) => i === index ? { ...item, displayName: event.target.value } : item))} /></div>
              <div><label htmlFor={`add-athlete-email-${index}`} className="mb-1 block text-sm font-medium">{t('email')}</label><Input id={`add-athlete-email-${index}`} type="email" value={player.email} onChange={(event) => setPlayers((current) => current.map((item, i) => i === index ? { ...item, email: event.target.value } : item))} /></div>
              <div><label htmlFor={`add-athlete-phone-${index}`} className="mb-1 block text-sm font-medium">{t('phone')}</label><Input id={`add-athlete-phone-${index}`} type="tel" value={player.phone} onChange={(event) => setPlayers((current) => current.map((item, i) => i === index ? { ...item, phone: event.target.value } : item))} /></div>
            </div>)}
          </>}
          <div><label htmlFor="add-athlete-team-name" className="mb-1 block text-sm font-medium">{t('teamName')}</label><Input id="add-athlete-team-name" value={teamName} onChange={(event) => setTeamName(event.target.value)} /></div>
          <div><label htmlFor="add-athlete-organizer-note" className="mb-1 block text-sm font-medium">{t('organizerNote')}</label><Textarea id="add-athlete-organizer-note" maxLength={280} rows={3} value={organizerNote} onChange={(event) => setOrganizerNote(event.target.value)} /><p className="mt-1 text-right text-xs text-slate-500">{organizerNote.length}/280</p></div>
          <p role="status" aria-live="polite" className="sr-only">{pageLoading ? t('loading') : ''}</p>
        </div>
        <ModalFooter>
          <Button type="button" variant="outline" onClick={() => onOpenChange(false)} disabled={submitting}>{t('cancel')}</Button>
          <Button type="button" onClick={() => void submit()} disabled={!canSubmit || submitting || !divisionId}>
            {submitting ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <UserPlus className="mr-2 h-4 w-4" />}{t('submit')}
          </Button>
        </ModalFooter>
      </ModalContent>
    </Modal>
  );
}

'use client';

import { useState } from 'react';
import { useTranslations } from 'next-intl';
import { Button } from '@/components/ui/Button';
import { tournamentsApi } from '@/features/tournaments/api';
import toast from 'react-hot-toast';
import { getErrorMessage } from '@/utils/error';
import { X, Users } from 'lucide-react';
import { useAuthStore } from '@/lib/zustand/authStore';
import { useRouter } from 'next/navigation';

interface Props {
  tournamentId: string;
  tournamentName: string;
  entryFee: number;
  matchType?: string;
  divisionId?: string;
  isRanked?: boolean;
  isOpen: boolean;
  onClose: () => void;
}

export default function RegisterModal({ tournamentId, divisionId, tournamentName, entryFee, matchType, isRanked = false, isOpen, onClose }: Props) {
  const { user, isAuthenticated } = useAuthStore();
  const router = useRouter();
  const translate = useTranslations('Common');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [partnerEmailOrPhone, setPartnerEmailOrPhone] = useState('');
  const [rankingConsent, setRankingConsent] = useState(false);

  const isDoubles = matchType === 'DOUBLES' || matchType === 'MIXED_DOUBLES';

  if (!isOpen) return null;

  const handleRegisterSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!isAuthenticated || !user) {
      toast.error(translate('loginToRegister'));
      window.location.assign(`/login?redirect=/tournaments/${tournamentId}`);
      return;
    }

    if (isRanked && !rankingConsent) {
      toast.error(translate('rankingConsentRequired'));
      return;
    }

    try {
      setIsSubmitting(true);
      const teamName = user?.fullName || translate('player');
      const payload: { teamName: string; partnerEmailOrPhone?: string; tournamentDivisionId?: string; rankingConsent: boolean } = {
        teamName,
        rankingConsent,
        ...(divisionId ? { tournamentDivisionId: divisionId } : {}),
      };
      if (isDoubles && partnerEmailOrPhone.trim()) {
        payload.partnerEmailOrPhone = partnerEmailOrPhone.trim();
      }

      const res = await tournamentsApi.register(tournamentId, payload);
      const participantId = res?.data?.participant?.id;
      const payableEntryFee = Number(res?.data?.entryFee ?? entryFee);
      const paymentEligible = res?.data?.paymentEligible === true;

      if (isDoubles && partnerEmailOrPhone.trim()) {
        toast.success(translate('partnerInviteSent'), { duration: 5000 });
      } else {
        toast.success(translate('registrationSuccess'));
      }
      onClose();

            if (paymentEligible && payableEntryFee > 0 && participantId) {

        router.push(`/payments/checkout?participantId=${participantId}&tournamentId=${tournamentId}`);
      } else {
        router.refresh();
      }
    } catch (error) {
      toast.error(getErrorMessage(error));
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-lg shadow-xl w-full max-w-md overflow-hidden">
        <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <h2 className="text-lg font-bold text-slate-900 flex items-center gap-2">
            <Users className="w-5 h-5 text-blue-600" /> {translate('registerForTournament')}
          </h2>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-6">
          <p className="text-sm text-slate-600 mb-5">
            {translate('registerDescription')} <strong className="text-slate-900">{tournamentName}</strong>.
          </p>

          <form onSubmit={handleRegisterSubmit} className="flex flex-col gap-4">
            <div className="bg-blue-50/70 border border-blue-200/80 rounded-lg p-4 flex items-center justify-between">
              <div>
                <p className="text-xs text-blue-600 font-semibold mb-0.5">{translate('registeredAthleteCaptain')}</p>
                <p className="text-base font-bold text-slate-900">{user?.fullName || translate('notUpdated')}</p>
                <p className="text-xs text-slate-500 mt-0.5">{translate('accountNameAuto')}</p>
              </div>
            </div>

            {isDoubles && (
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-700">{translate('partnerLabel')}</label>
                <input
                  type="text"
                  placeholder="{translate('partnerPlaceholder')}"
                  value={partnerEmailOrPhone}
                  onChange={(e) => setPartnerEmailOrPhone(e.target.value)}
                  className="w-full px-3 py-2 text-sm border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none"
                />
                <p className="text-xs text-amber-700 bg-amber-50 p-2.5 rounded-md border border-amber-200 leading-snug">
                  ⏱️ <strong>{translate('pairingDeadline')}:</strong> {translate('pairingDeadlineNotice', { hours: 1 })}
                </p>
              </div>
            )}

            <div className="bg-slate-50 border border-slate-200/80 p-4 rounded-lg">
              <p className="text-xs text-slate-600 font-medium leading-relaxed">
                {translate('registrationTermsNotice')}
              </p>
            </div>

            {isRanked && (
              <label className="flex items-start gap-3 rounded-xl border border-sky-200 bg-sky-50 p-3 text-sm text-slate-700">
                <input
                  type="checkbox"
                  checked={rankingConsent}
                  onChange={(event) => setRankingConsent(event.target.checked)}
                  className="mt-1 h-4 w-4 accent-sky-600"
                />
                <span>{translate('rankingConsentLabel')}</span>
              </label>
            )}

            <div className="flex justify-end gap-3 mt-4">
              <Button type="button" variant="outline" onClick={onClose} className="border-slate-200 text-slate-600">
                {translate('cancel')}
              </Button>
              <Button type="submit" disabled={isSubmitting} className="bg-blue-600 hover:bg-blue-700 text-white font-semibold">
                {isSubmitting ? translate('processing') : translate('confirmRegistration')}
              </Button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useTranslations } from 'next-intl';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { footballTeamsApi, tournamentsApi, type FootballRosterStatus, type FootballTeam } from '@/features/tournaments/api';
import { getErrorMessage } from '@/utils/error';
import { Check, Loader2, Plus, ShieldCheck, Users } from 'lucide-react';
import toast from 'react-hot-toast';

import RegistrationCustomFields, { validateRegistrationResponses } from './RegistrationCustomFields';
import { normalizeRegistrationResponses, type RegistrationField } from '@/features/tournaments/registration-form';

interface Props {
  tournamentId: string;
  inviteCode?: string;
  divisionId?: string;
  categoryId?: string;
  currentUserId?: string;
  participantId?: string;
  participantTeamId?: string | null;
  rosterLockedAt?: string | null;
  teamSize: number;
  maxTeamSize?: number;
  maxReserve?: number;
  registrationMode?: string;
  isRanked?: boolean;
  rankingConsent?: boolean;
  onRankingConsentChange?: (value: boolean) => void;
  rankingConsentLabel?: string;
  rankingConsentCondition?: string;
  rankingConsentRequiredMessage?: string;
  customResponses?: Record<string, unknown>;
  onCustomResponsesChange?: (updater: (current: Record<string, unknown>) => Record<string, unknown>) => void;
  registrationFields?: RegistrationField[];
  onRegistrationChanged?: () => Promise<void> | void;
  /** Hạn chót hiệu lực của nội dung đã qua — xem DoublesRegistrationFlow. */
  registrationExpired?: boolean;
}

export default function TeamRegistrationFlow({
  tournamentId, inviteCode, divisionId, categoryId, currentUserId, participantId, participantTeamId, rosterLockedAt, teamSize, maxTeamSize, maxReserve = 0, registrationMode, isRanked = false, rankingConsent = false, onRankingConsentChange, rankingConsentLabel, rankingConsentCondition, rankingConsentRequiredMessage, customResponses, onCustomResponsesChange, registrationFields,
  onRegistrationChanged,
  registrationExpired = false,
}: Props) {
  const router = useRouter();
  const translate = useTranslations('TeamRegistration');
  const registrationTranslate = useTranslations('TournamentRegistration');
  const [teams, setTeams] = useState<FootballTeam[]>([]);
  const [selectedId, setSelectedId] = useState('');
  const [newName, setNewName] = useState('');
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [teamMembers, setTeamMembers] = useState<NonNullable<FootballTeam['members']>>([]);
  const [selectedMemberIds, setSelectedMemberIds] = useState<string[]>([]);
  const [selectedReserveIds, setSelectedReserveIds] = useState<string[]>([]);
  const [rosterStatus, setRosterStatus] = useState<FootballRosterStatus | null>(null);
  const [rosterLoading, setRosterLoading] = useState(Boolean(participantId));
  const cap = maxTeamSize ?? teamSize + maxReserve;

  useEffect(() => {
    if (!selectedId) return;
    let active = true;
    footballTeamsApi.get(selectedId).then(async (res) => {
      if (!active) return;
      const members = (res.data?.members ?? []).filter((member) => member.status === undefined || member.status === 'ACTIVE');
      setTeamMembers(members);
      const ids = members.map((member) => member.userId);
      const orderedIds = [
        ...(currentUserId && ids.includes(currentUserId) ? [currentUserId] : []),
        ...ids.filter((id) => id !== currentUserId),
      ];
      if (participantId) {
        try {
          const status = (await tournamentsApi.getFootballRosterStatus(tournamentId, participantId)).data;
          if (!active) return;
          setRosterStatus(status);
          setSelectedMemberIds(status.roster.filter((row) => row.role === 'MAIN').map((row) => row.userId).filter((id) => ids.includes(id)));
          setSelectedReserveIds(status.roster.filter((row) => row.role === 'RESERVE').map((row) => row.userId).filter((id) => ids.includes(id)));
        } catch {
          if (active) {
            setSelectedMemberIds(orderedIds.slice(0, teamSize));
            setSelectedReserveIds([]);
          }
        }
      } else {
        setSelectedMemberIds(orderedIds.slice(0, teamSize));
        setSelectedReserveIds([]);
      }
    }).catch(() => { if (active) { setTeamMembers([]); setSelectedMemberIds([]); } }).finally(() => { if (active) setRosterLoading(false); });
    return () => { active = false; };
  }, [currentUserId, participantId, selectedId, teamSize, tournamentId]);

  useEffect(() => {
    let active = true;
    footballTeamsApi.listMine().then((res) => {
      if (!active) return;
      const rows = (res.data ?? []).map((row) => row.team).filter((team) => team.status === 'ACTIVE' && team.categoryId === categoryId);
      setTeams(rows);
      const preferred = participantTeamId ? rows.find((row) => row.id === participantTeamId) : undefined;
      if (preferred || rows[0]) setSelectedId((preferred ?? rows[0]).id);
    }).catch(() => { if (active) setTeams([]); }).finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [categoryId, participantTeamId]);

  const createTeam = async () => {
    const name = newName.trim();
    if (!name || !categoryId) return toast.error(translate('createTeamValidation'));
    setSaving(true);
    try {
      const res = await footballTeamsApi.create({ name, categoryId });
      const team = res.data;
      setTeams((current) => [team, ...current]);
      setSelectedId(team.id);
      setNewName('');
      toast.success(translate('teamCreated'));
    } catch (error) { toast.error(getErrorMessage(error)); }
    finally { setSaving(false); }
  };

  const submit = async () => {
    const team = teams.find((item) => item.id === selectedId);
    if (!team) return toast.error(translate('selectTeam'));
    if (!participantId && isRanked && !rankingConsent) {
      return toast.error(rankingConsentRequiredMessage || translate('selectTeam'));
    }
    const submittedCustomResponses = normalizeRegistrationResponses(customResponses || {});
    if (!participantId && registrationFields && registrationFields.length > 0) {
      const customValidationError = validateRegistrationResponses(registrationFields, submittedCustomResponses, registrationTranslate);
      if (customValidationError) {
        toast.error(customValidationError);
        return;
      }
    }
    setSaving(true);
    try {
      if (participantId) {
        await tournamentsApi.updateFootballRoster(tournamentId, participantId, {
          memberIds: selectedMemberIds,
          reserveMemberIds: selectedReserveIds,
        });
        toast.success(selectedMemberIds.length < teamSize ? translate('draftRosterSaved') : translate('rosterUpdated'));
        await onRegistrationChanged?.();
        router.refresh();
        return;
      }
      const res = await tournamentsApi.register(tournamentId, {
        teamName: team.name,
        footballTeamId: team.id,
        memberIds: selectedMemberIds,
        reserveMemberIds: selectedReserveIds,
        inviteCode,
        divisionId,
        tournamentDivisionId: divisionId,
        rankingConsent: isRanked ? rankingConsent : true,
        customResponses: submittedCustomResponses,
      });
      const createdParticipantId = res.data?.participant?.id;
      if (createdParticipantId && res.data?.paymentEligible === true) {
        router.push(`/payments/checkout?participantId=${createdParticipantId}&tournamentId=${tournamentId}&divisionId=${divisionId || ''}`);
      } else {
        const isDraft = selectedMemberIds.length < teamSize;
        toast.success(
          isDraft
            ? translate('draftRegistrationSaved')
            : registrationMode === 'APPROVAL'
              ? translate('approvalSubmitted')
            : translate('registrationSuccess'),
        );
        await onRegistrationChanged?.();
        router.refresh();
      }
    } catch (error) { toast.error(getErrorMessage(error)); }
    finally { setSaving(false); }
  };

  return (
    <div className="space-y-5 animate-in fade-in duration-300">
      <div className="rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3">
        <p className="flex items-center gap-2 text-sm font-bold text-emerald-900"><ShieldCheck className="h-4 w-4" /> {translate('registerByTeam')}</p>
        <p className="mt-1 text-xs font-semibold text-emerald-700">{translate('teamFormationLimits', { teamSize, maxReserve, cap })}</p>
      </div>

      {!participantId && registrationFields && registrationFields.length > 0 && (
        <div className="border-b border-slate-200/80 pb-4">
          <RegistrationCustomFields
            tournamentId={tournamentId}
            fields={registrationFields}
            responses={customResponses || {}}
            onChange={(fieldId, value) =>
              onCustomResponsesChange?.((current) => ({ ...current, [fieldId]: value }))
            }
            borderless
          />
        </div>
      )}
      {participantId && (rosterStatus?.entry?.status === 'LOCKED' || rosterLockedAt) && <p className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-xs font-semibold text-amber-800">{translate('rosterLockedView')}</p>}
      {loading ? <div className="flex items-center justify-center py-8 text-sm text-slate-400"><Loader2 className="mr-2 h-4 w-4 animate-spin" /> {translate('loadingTeams')}</div> : (
        <>
          <div className="space-y-2">
            <p className="flex items-center gap-2 text-sm font-bold text-slate-700"><Users className="h-4 w-4" /> {translate('eligibleTeams')}</p>
            {teams.length === 0 ? <p className="rounded-lg border border-dashed border-slate-300 px-4 py-5 text-center text-xs font-semibold text-slate-500">{translate('noSuitableTeam')}</p> : (
              <div className="grid gap-2">
                {teams.map((team) => <button key={team.id} type="button" disabled={Boolean(participantId)} onClick={() => setSelectedId(team.id)} className={`flex items-center gap-3 rounded-lg border p-3 text-left transition ${selectedId === team.id ? 'border-emerald-500 bg-emerald-50 ring-1 ring-emerald-500' : 'border-slate-200 bg-white hover:border-emerald-300'} disabled:cursor-not-allowed disabled:opacity-70`}>
                  <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-slate-100 text-sm font-black text-slate-500">{team.name.slice(0, 2).toUpperCase()}</div>
                  <span className="min-w-0 flex-1"><b className="block truncate text-sm text-slate-900">{team.name}</b><small className="text-xs font-semibold text-slate-500">{team.membership?.role === 'PLAYER' ? translate('memberRole') : translate('registrationPermission')} · {translate('manageTeamHint')}</small></span>
                  {selectedId === team.id && <Check className="h-5 w-5 text-emerald-600" />}
                </button>)}
              </div>
            )}
          </div>
          <div className="rounded-lg border border-slate-200 bg-slate-50 p-3">
            <p className="mb-2 text-xs font-bold uppercase tracking-wide text-slate-500">{translate('quickCreateTeam')}</p>
            <div className="flex gap-2"><Input value={newName} onChange={(event) => setNewName(event.target.value)} placeholder={translate('teamNamePlaceholder')} /><Button type="button" onClick={createTeam} disabled={saving || !newName.trim()} variant="outline"><Plus className="h-4 w-4" /> {translate('create')}</Button></div>
            <p className="mt-2 text-xs font-semibold text-slate-400">{translate('manageTeamHint')}</p>
          </div>
          {teamMembers.length > 0 && (
            <div className="rounded-lg border border-slate-200 bg-white p-3">
              <p className="mb-1 text-sm font-bold text-slate-800">{translate('rosterTitle')}</p>
              <p className="mb-3 text-xs font-semibold text-slate-500">{translate('rosterInstructions', { teamSize, maxReserve })}</p>
              <div className="grid gap-2 sm:grid-cols-2">
                {teamMembers.map((member) => {
                  const isMain = selectedMemberIds.includes(member.userId);
                  const isReserve = selectedReserveIds.includes(member.userId);
                  return <div key={member.userId} className="flex items-center gap-2 rounded-md border border-slate-100 px-2 py-2 text-xs font-semibold text-slate-700">
                    <span className="min-w-0 flex-1 truncate">{member.profile?.fullName || member.userId.slice(0, 8)}</span>
                    {member.role !== 'PLAYER' && <span className="text-xs text-slate-400">{member.role}</span>}
                    <button type="button" disabled={Boolean(rosterStatus?.entry?.status === 'LOCKED' || rosterLockedAt) || (!isMain && selectedMemberIds.length >= teamSize)} className={`rounded px-2 py-1 text-xs font-bold disabled:cursor-not-allowed disabled:opacity-40 ${isMain ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-500'}`} onClick={() => {
                      setSelectedMemberIds((current) => isMain ? current.filter((id) => id !== member.userId) : [...current.filter((id) => id !== member.userId), member.userId]);
                      setSelectedReserveIds((current) => current.filter((id) => id !== member.userId));
                    }}>{translate('mainRole')}</button>
                    <button type="button" disabled={Boolean(rosterStatus?.entry?.status === 'LOCKED' || rosterLockedAt) || (!isReserve && selectedReserveIds.length >= maxReserve)} className={`rounded px-2 py-1 text-xs font-bold disabled:cursor-not-allowed disabled:opacity-40 ${isReserve ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-500'}`} onClick={() => {
                      setSelectedReserveIds((current) => isReserve ? current.filter((id) => id !== member.userId) : [...current.filter((id) => id !== member.userId), member.userId]);
                      setSelectedMemberIds((current) => current.filter((id) => id !== member.userId));
                    }}>{translate('reserveRole')}</button>
                    </div>;
                })}
              </div>
              <p className="mt-3 text-xs font-semibold text-slate-500">{translate('selectedSummary', { main: selectedMemberIds.length, reserve: selectedReserveIds.length, maxReserve })}</p>
            </div>
          )}
        </>
      )}
      {!participantId && isRanked && rankingConsentLabel && (
        <label className="flex items-start gap-3 rounded-xl border border-sky-200 bg-sky-50 p-3.5 text-sm text-slate-700">
          <input
            type="checkbox"
            checked={rankingConsent}
            onChange={(event) => onRankingConsentChange?.(event.target.checked)}
            className="mt-1 h-4 w-4 accent-sky-600"
          />
          <span>
            {rankingConsentLabel}
            {rankingConsentCondition && <span className="mt-1 block text-xs text-slate-500">{rankingConsentCondition}</span>}
          </span>
        </label>
