  | "PICKLEBALL_RALLY"
  | "PICKLEBALL_SIDE_OUT"
  | "TENNIS"
  | "FOOTBALL";
export type SportScoringModel =
  "RALLY_POINT_SET" | "TENNIS_SET" | "PICKLEBALL_SIDE_OUT";

export interface SportRuleScoringConfig {
  mode?: "LITE" | "STRICT";
  /** Legacy/Quick scoring discriminator; FREE and OPEN mean unbounded sets. */
  scoringMode?: string;
  scoring_mode?: string;
  rulesPreset?: string;
  kind?: SportRuleKind;
  scoringModel?: SportScoringModel;
  setsToWin?: number;
  sets_to_win?: number;
  pointsPerSet?: number;
  points_per_set?: number;
  winByTwo?: boolean;
  mustWinByTwo?: boolean;
  deuceEnabled?: boolean;
  deuce_enabled?: boolean;
  tiebreakAt?: number;
  tiebreak_at?: number;
  tiebreakPoints?: number;
  tiebreak_points?: number;
  maxPoints?: number;
  max_points?: number;
  maxPointsPerSet?: number;
  maxDeucePoints?: number | null;
  superTiebreakEnabled?: boolean;
  superTiebreakSetIndex?: number | null;
  superTiebreakPoints?: number | null;
  [key: string]: unknown;
}

export interface SportRulesEnvelope extends SportRuleScoringConfig {
  version?: number;
  kind?: SportRuleKind;
  scoringModel?: SportScoringModel;
  format?: Record<string, unknown>;
  scoring?: SportRuleScoringConfig;
}

export interface StageRoundRuleConfig extends SportRuleScoringConfig {
  venue_id?: string | null;
  scheduled_date?: string | null;
  custom_notes?: string | null;
}

