  advanceMapping?: {
    numGroups?: number;
    teamsAdvancing?: number;
    allowWildcard?: boolean;
    wildcardTeams?: number;
    totalAdvancing?: number;
  };
}
/**
 * Additive roster-weighted capacity projection for a division.
 *
 * `maxParticipants` is a TEAM limit, so doubles/mixed divisions report
 * fractional `occupiedTeamSlots`: one active roster member holds half a team.
 * WAITLISTED and terminal states reserve nothing. Aggregates only — the
 * projection never carries participant identity. `_count.participants` and
 * `_summary.participantCount` stay plain participant row counts.
