'use client';

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useTranslations, useLocale } from 'next-intl';
import Link from 'next/link';
import { Plus, X, ArrowUpRight, Loader2, Trophy, AlertCircle, ChevronLeft, ChevronRight, User } from 'lucide-react';
import { tournamentsApi, type Tournament, type TournamentParticipant } from '@/features/tournaments/api';
import { communitiesApi, type Community } from '@/features/communities/api';
import { useAuthStore } from '@/lib/zustand/authStore';
import { getErrorMessage } from '@/utils/error';
import toast from 'react-hot-toast';
import { cn } from '@/utils/cn';
import { JoinCommunityModal } from '@/components/shared/JoinCommunityModal';
import { areAllDivisionsFull, formatDivisionCapacity, isDivisionFull } from '@/features/tournaments/capacity/division-capacity';
import EntityBrandAvatar from '@/components/ui/EntityBrandAvatar';

interface CommunityTournamentRosterWidgetProps {
  tournamentId: string;
  communityId?: string;
  communityLogoUrl?: string | null;
  clubName?: string | null;
  hideHeader?: boolean;
  initialTournamentName?: string;
  categoryName?: string | null;
  status?: string;
  inviteCode?: string | null;
  maxParticipants?: number | null;
  startDate?: string | null;
}

const BG_COLORS = [
  'bg-emerald-500',
  'bg-blue-500',
  'bg-amber-500',
  'bg-purple-500',
  'bg-rose-500',
  'bg-indigo-500',
  'bg-teal-500',
  'bg-cyan-500',
];

const SLOTS_PER_PAGE = 16;

function getInitials(name: string): string {
  const parts = name.trim().split(/\s+/);
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

function getColorByName(name: string): string {
  let hash = 0;
  for (let i = 0; i < name.length; i++) {
    hash = name.charCodeAt(i) + ((hash << 5) - hash);
  }
  return BG_COLORS[Math.abs(hash) % BG_COLORS.length];
}

export default function CommunityTournamentRosterWidget({
  tournamentId,
  communityId,
  communityLogoUrl,
  clubName,
  hideHeader = false,
  initialTournamentName,
  categoryName,
  status,
  inviteCode: initialInviteCode,
  maxParticipants: initialMaxParticipants,
}: CommunityTournamentRosterWidgetProps) {
  const commonTranslate = useTranslations('Common');
  const { user } = useAuthStore();

  const [tournament, setTournament] = useState<Tournament | null>(null);
  const [selectedDivisionId, setSelectedDivisionId] = useState('');
  const [participants, setParticipants] = useState<TournamentParticipant[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [isJoining, setIsJoining] = useState<boolean>(false);
  const [isWithdrawing, setIsWithdrawing] = useState<boolean>(false);
  const [currentPage, setCurrentPage] = useState<number>(1);
  const [selectedUserToWithdraw, setSelectedUserToWithdraw] = useState<TournamentParticipant | null>(null);
  const [communityLogo, setCommunityLogo] = useState<string | null>(null);
  const [community, setCommunity] = useState<Community | null>(null);
  const [membershipStatus, setMembershipStatus] = useState<string | null>(null);
  const [isJoinCommunityOpen, setIsJoinCommunityOpen] = useState(false);

  const fetchTournamentAndParticipants = useCallback(async () => {
    try {
      const [tourneyRes, partRes] = await Promise.all([
        tournamentsApi.getTournamentById(tournamentId).catch(() => null),
        tournamentsApi.getTournamentParticipants(tournamentId).catch(() => null),
      ]);

      let effectiveCommId = communityId;
      const tourneyData = (tourneyRes as any)?.data ?? tourneyRes;
      if (tourneyData && typeof tourneyData === 'object' && 'id' in tourneyData) {
        setTournament(tourneyData);
        const activeDivisions = (tourneyData.divisions ?? []).filter(
          (division: NonNullable<Tournament['divisions']>[number]) =>
            division.status?.toUpperCase() !== 'CANCELLED',
        );
        setSelectedDivisionId((current) =>
          activeDivisions.some(
            (division: NonNullable<Tournament['divisions']>[number]) =>
              division.id === current,
          )
            ? current
            : activeDivisions.length === 1
              ? activeDivisions[0].id
              : '',
        );
        if (tourneyData.communityId) {
          effectiveCommId = tourneyData.communityId;
        }
      }
      if (effectiveCommId) {
        const communityResponse = await communitiesApi.getCommunityById(effectiveCommId);
        setCommunity(communityResponse.data);
        if (user?.id) {
…
        }
      }
…
    } catch (err) {
…
    }
  }, [tournamentId, communityId, user]);
…
}

