  useEffect(() => {
    fetchTournamentAndParticipants();
  }, [fetchTournamentAndParticipants]);

  const activeDivisions = (tournament?.divisions ?? []).filter(
    (division) => division.status?.toUpperCase() !== 'CANCELLED',
  );
  const selectedDivision = activeDivisions.find(
    (division) => division.id === selectedDivisionId,
  );
  const effectiveInviteCode =
    selectedDivision?.inviteCode ||
    (activeDivisions.length === 1 ? activeDivisions[0]?.inviteCode : null) ||
    initialInviteCode;
  const effectiveMaxParticipants =
    tournament?.divisions?.[0]?.maxParticipants ||
    tournament?.tournamentConfig?.maxTeams ||
    initialMaxParticipants ||
    16;

  // Roster-weighted capacity comes from the server. A doubles row is one
  // athlete, not one team, so a participant row count never decides fullness.
  const capacityDivisions = tournament?.divisions ?? [];
  const capacityMatchType = capacityDivisions[0]?.matchType ?? tournament?.matchType ?? null;
  const isDoublesDivision = ['DOUBLES', 'MIXED_DOUBLES'].includes(String(capacityMatchType ?? '').toUpperCase());
  const tournamentCapacitySource = {
    matchType: capacityMatchType,
    maxParticipants: capacityDivisions[0]?.maxParticipants ?? tournament?.maxParticipants ?? effectiveMaxParticipants,
    capacity: capacityDivisions[0]?.capacity ?? tournament?.capacity ?? null,
    // Without a projection fall back to the widget's own active roster count,
    // which already excludes withdrawn/rejected rows.
    _count: { participants: participants.length },
  };
  // A category with room must stay joinable, so the join action closes only
  // when every division of the tournament reports full.
  const isAtTeamCapacity = capacityDivisions.length > 0
