  const handleJoin = async () => {
    if (!user) {
      toast.error(isVi ? 'Vui lòng đăng nhập để xác nhận tham gia giải đấu' : 'Please sign in to join the tournament');
      return;
    }

    if (isUserRegistered) {
      toast(isVi ? 'Bạn đã có tên trong danh sách tham gia' : 'You are already registered');
      return;
    }

    if (tournament?.communityId && membershipStatus !== 'JOINED') {
      setIsJoinCommunityOpen(true);
      return;
    }

    if (isAtTeamCapacity) {
      toast.error(isVi ? 'Giải đấu đã đủ số lượng người tham gia' : 'Tournament is full');
      return;
    }

    if (activeDivisions.length > 1 && !selectedDivisionId) {
      toast.error(commonTranslate('selectDivisionForRegistration'));
      return;
    }
    try {
      setIsJoining(true);
      if (effectiveInviteCode) {
        await tournamentsApi.joinLite(
          effectiveInviteCode,
          selectedDivisionId || undefined,
        );
      } else {
        await tournamentsApi.register(tournamentId, {
          teamName: user.fullName || 'VĐV',
          tournamentDivisionId: selectedDivisionId || undefined,
        });
      }
      toast.success(isVi ? 'Đã xác nhận tham gia giải đấu!' : 'Joined tournament successfully!');
      await fetchTournamentAndParticipants();
    } catch (err: unknown) {
      toast.error(
