  const loadRegistration = useCallback(async () => {
    setIsCheckingInitial(true);
    setRegistrationLookupFailed(false);
    try {
      // One active application is allowed per tournament; a stale division filter can hide it after reload.
      const res = await tournamentsApi.getMyRegistration(tournamentId);
      if (!res.data?.registered) {
        setParticipant(null);
        setPairingMode(defaultDoublesPairingMode);
        setStep(1);
        return;
      }
      if (!res.data.participant) {
        setRegistrationLookupFailed(true);
        return;
      }
      const part = normalizeRegistrationParticipant(
        res.data.participant,
        undefined,
        res.data.paymentEligible,
      );
